// Generated by /ship coverage audit
// Value: protects=a native list row action runs the matching article action on the tapped article, and a stale row id does nothing;
//   fails_when=an action id maps to another handler, the wrong article is used, a payload changes, or an unknown id triggers a mutation or share;
//   why_new=useArticleRowActions had no test, so mis-wired save, hide, share, source or report taps would only show on a device;
//   seam=none;
//   no_claim=green does not prove the native list reports these ids or that the mutation updates the cached list.
import { afterEach, beforeEach, describe, expect, mock, spyOn, test } from "bun:test";
import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import type { ArticleListItemDto } from "@kyomi/reader/schemas/article";

const alert = mock((..._args: unknown[]) => undefined);
const openURL = mock(async (_url: string) => true);
const share = mock(async (_content: unknown) => ({ action: "sharedAction" }));
const selectionAsync = mock(async () => undefined);
const mutateAsync = mock(async (_input: unknown) => ({ message: "ok" }));
const fetchMock = mock(
  async (_url: string, _init: RequestInit) =>
    new Response(JSON.stringify({ message: "ok" }), { status: 200 }),
);
const originalFetch = globalThis.fetch;

// React Native, Expo and the secure-store backed auth client cannot load under bun, so only they
// and the react-query mutation are stubbed. The real haptics helper and fetchMobileApiJson run.
mock.module("react-native", () => ({
  Alert: { alert },
  Linking: { openURL },
  Platform: { OS: "ios" },
  Share: { share },
}));
mock.module("expo-haptics", () => ({
  AndroidHaptics: { Toggle_Off: "toggle-off", Toggle_On: "toggle-on" },
  performAndroidHapticsAsync: async () => undefined,
  selectionAsync,
}));
mock.module("../../../../../../apps/mobile/src/lib/auth", () => ({
  getAuthCookie: () => "",
  resolveAuthOrigin: () => "https://api.kyomi.test",
}));
mock.module("../../../../../../apps/mobile/src/modules/inbox/hooks/use-state", () => ({
  useArticleStateMutation: () => ({ isPending: false, mutateAsync }),
}));

const { useArticleRowActions } =
  await import("../../../../../../apps/mobile/src/modules/inbox/hooks/use-actions");

const item = (overrides: Partial<ArticleListItemDto> = {}): ArticleListItemDto => ({
  articleType: "feed",
  categories: [],
  feedFaviconUrl: null,
  feedId: "feed-id",
  feedSiteUrl: "https://example.com",
  feedTitle: "Example",
  feedUrl: "https://example.com/feed.xml",
  id: "article-1",
  isRead: false,
  isSaved: false,
  lastViewedAt: null,
  link: "https://example.com/posts/1",
  publishedAt: "2026-08-05T10:00:00.000Z",
  summary: "A short summary.",
  title: "Article 1",
  ...overrides,
});

const FIRST = item();
const SECOND = item({
  id: "article-2",
  link: "https://example.com/posts/2",
  summary: null,
  title: "Article 2",
});
const SAVED = item({ id: "article-3", isSaved: true, title: "Article 3" });

function mountRowActions(items: readonly ArticleListItemDto[]) {
  let dispatch: ReturnType<typeof useArticleRowActions> | undefined;

  function Probe() {
    dispatch = useArticleRowActions(items);
    return null;
  }

  renderToStaticMarkup(createElement(Probe));
  if (!dispatch) throw new Error("the hook did not render");
  return dispatch;
}

/** Lets the promise chains inside the fire-and-forget actions settle. */
const settle = () => new Promise((resolve) => setTimeout(resolve, 0));

let consoleError: ReturnType<typeof spyOn>;

beforeEach(() => {
  consoleError = spyOn(console, "error").mockImplementation(() => {});
  for (const spy of [alert, openURL, share, selectionAsync, mutateAsync, fetchMock]) {
    spy.mockClear();
  }
  globalThis.fetch = fetchMock as unknown as typeof fetch;
});

afterEach(() => {
  consoleError.mockRestore();
  globalThis.fetch = originalFetch;
  fetchMock.mockImplementation(
    async () => new Response(JSON.stringify({ message: "ok" }), { status: 200 }),
  );
  mutateAsync.mockImplementation(async () => ({ message: "ok" }));
  openURL.mockImplementation(async () => true);
  share.mockImplementation(async () => ({ action: "sharedAction" }));
});

describe("useArticleRowActions routing", () => {
  test("toggleSaved flips the saved state of the tapped article and gives selection feedback", async () => {
    const dispatch = mountRowActions([FIRST, SAVED]);

    dispatch(FIRST.id, "toggleSaved");
    dispatch(SAVED.id, "toggleSaved");
    await settle();

    expect(mutateAsync.mock.calls).toEqual([
      [{ itemId: "article-1", patch: { isSaved: true } }],
      [{ itemId: "article-3", patch: { isSaved: false } }],
    ]);
    expect(selectionAsync).toHaveBeenCalledTimes(2);
  });

  test("hide hides the article and removes it from the list", async () => {
    mountRowActions([FIRST, SECOND])(SECOND.id, "hide");
    await settle();

    expect(mutateAsync.mock.calls).toEqual([
      [{ itemId: "article-2", patch: { isHidden: true }, removeFromList: true }],
    ]);
  });

  test("share sends title, summary and link, and leaves the summary out when there is none", async () => {
    const dispatch = mountRowActions([FIRST, SECOND]);

    dispatch(FIRST.id, "share");
    dispatch(SECOND.id, "share");
    await settle();

    expect(share.mock.calls).toEqual([
      [
        {
          message: "Article 1\nA short summary.\nhttps://example.com/posts/1",
          title: "Article 1",
          url: "https://example.com/posts/1",
        },
      ],
      [
        {
          message: "Article 2\nhttps://example.com/posts/2",
          title: "Article 2",
          url: "https://example.com/posts/2",
        },
      ],
    ]);
  });

  test("openSource opens the link of the tapped article", async () => {
    mountRowActions([FIRST, SECOND])(SECOND.id, "openSource");
    await settle();

    expect(openURL.mock.calls).toEqual([["https://example.com/posts/2"]]);
  });

  test("report posts a broken-article report for the tapped article and confirms it", async () => {
    mountRowActions([FIRST, item({ id: "a/b c", title: "Odd id" })])("a/b c", "report");
    await settle();

    expect(fetchMock).toHaveBeenCalledTimes(1);
    const [url, init] = fetchMock.mock.calls[0] ?? [];
    expect(url).toBe("https://api.kyomi.test/api/v1/articles/a%2Fb%20c/reports/broken");
    expect(init?.method).toBe("POST");
    expect(init?.body).toBe(JSON.stringify({ reason: "broken_article" }));
    expect(new Headers(init?.headers).get("content-type")).toBe("application/json");
    expect(alert.mock.calls).toEqual([["Report sent", "Thanks for helping improve Kyomi."]]);
  });

  test("does nothing for an id that is not in the list", async () => {
    const dispatch = mountRowActions([FIRST, SECOND]);

    for (const action of ["hide", "openSource", "report", "share", "toggleSaved"] as const) {
      dispatch("stale-article", action);
    }
    await settle();

    expect(mutateAsync).not.toHaveBeenCalled();
    expect(selectionAsync).not.toHaveBeenCalled();
    expect(share).not.toHaveBeenCalled();
    expect(openURL).not.toHaveBeenCalled();
    expect(fetchMock).not.toHaveBeenCalled();
    expect(alert).not.toHaveBeenCalled();
  });
});

describe("useArticleRowActions failures", () => {
  test("tells the user when saving or hiding fails, with wording for the save direction", async () => {
    mutateAsync.mockImplementation(async () => {
      throw new Error("offline");
    });
    const dispatch = mountRowActions([FIRST, SAVED]);

    dispatch(FIRST.id, "toggleSaved");
    dispatch(SAVED.id, "toggleSaved");
    dispatch(FIRST.id, "hide");
    await settle();

    expect(alert.mock.calls).toEqual([
      ["Unable to update article", "Unable to save article."],
      ["Unable to update article", "Please try again."],
      ["Unable to update article", "Please try again."],
    ]);
  });

  test("reports a link that cannot be opened and a report that could not be sent", async () => {
    openURL.mockImplementation(async () => {
      throw new Error("no handler");
    });
    fetchMock.mockImplementation(async () => new Response("nope", { status: 500 }));
    const dispatch = mountRowActions([FIRST]);

    dispatch(FIRST.id, "openSource");
    dispatch(FIRST.id, "report");
    await settle();

    expect(alert.mock.calls).toEqual([
      ["Unable to update article", "Unable to open the source."],
      ["Unable to update article", "Unable to send the report."],
    ]);
  });

  test("stays silent when the share sheet is dismissed or fails", async () => {
    share.mockImplementation(async () => {
      throw new Error("dismissed");
    });

    mountRowActions([FIRST])(FIRST.id, "share");
    await settle();

    expect(share).toHaveBeenCalledTimes(1);
    expect(alert).not.toHaveBeenCalled();
  });
});
